package com.bank.compsched.service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Feasibility check via Kahn's algorithm: can all tasks be placed.
public class ComplianceScheduleService {
    private static final Logger log = Logger.getLogger(ComplianceScheduleService.class.getName());

    public boolean canFinishAll(int taskCount, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < taskCount; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[taskCount];
        for (int[] p : prerequisites) {             // p = {prerequisite, dependent}
            adj.get(p[0]).add(p[1]);
            indeg[p[1]]++;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < taskCount; i++)
            if (indeg[i] == 0) queue.add(i);
        int placed = 0;
        while (!queue.isEmpty()) {
            int t = queue.poll();
            placed++;                               // one more task safely scheduled
            for (int next : adj.get(t))
                if (--indeg[next] == 0) queue.add(next);
        }
        boolean feasible = placed == taskCount;     // all placed means no cycle
        if (!feasible) log.severe("Cycle in compliance tasks: cannot finish all");
        else log.info(() -> "All " + taskCount + " compliance tasks can finish");
        return feasible;
    }
}
